int cm_rig_count(void) { return (int)(sizeof RIGS / sizeof RIGS[0]); }
const cm_rig *cm_rig_at(int i) { return i >= 0 && i < cm_rig_count() ? &RIGS[i] : 0; }
const cm_rig *cm_rig_find(const char *name) {
  int i;
  for (i = 0; i < cm_rig_count(); i++) if (!strcmp(RIGS[i].name, name)) return &RIGS[i];
  return 0;
}
